// 버전 표시: "v1.2.4 · 10/31 22:05 업데이트"
function verText(s) {
  let t = 'v' + (s.version || '?');
  if (s.updated) {
    const d = new Date(s.updated), p = (n) => String(n).padStart(2, '0');
    t += ` · ${d.getMonth() + 1}/${d.getDate()} ${p(d.getHours())}:${p(d.getMinutes())} 업데이트`;
  }
  return t;
}

