// 강제 종료 감시 (Windows 작업 스케줄러)
// 작업 관리자에서 손님 프로그램과 감시 프로그램을 한꺼번에 끄면 둘 다 다시 켜 줄 수 없다.
// 그래서 윈도우 작업 스케줄러가 1분마다 작은 스크립트(guard.vbs)를 실행해 확인한다.
// - 프로그램이 실행 중이면 running 파일에 프로세스 번호를 적어 둔다 (15초마다).
// - 정상 종료(관리자 PIN, 업데이트, 윈도우 종료)할 때는 running 파일을 지운다.
// - running 파일이 있는데 그 프로세스가 없으면 강제 종료로 보고 안내창을 띄운 뒤 1분 뒤 PC를 끈다.
// - 정전 등으로 꺼졌다 켜진 경우(running 파일이 부팅 시각보다 오래됐거나 3분 넘게 갱신이 없음)는 무시한다.
const fs = require('fs');
const path = require('path');
const { execFile } = require('child_process');

const TASK = 'PCBangGuard';
const MESSAGE = 'PC방 프로그램이 강제로 종료되었습니다. 약속에 따라 1분 뒤 이 PC가 자동으로 꺼집니다. 작업을 저장하세요.';

function vbs(runFile, exeName) {
  const q = (s) => s.replace(/"/g, '""');
  return `' PC방 강제 종료 감시 (자동 생성 파일)
Option Explicit
On Error Resume Next
Dim fso, wmi, sh, runFile, pid
Set fso = CreateObject("Scripting.FileSystemObject")
Set sh = CreateObject("WScript.Shell")
Set wmi = GetObject("winmgmts:\\\\.\\root\\cimv2")
runFile = "${q(runFile)}"

Function Alive()
  Dim f, p, procs
  Alive = True
  If Not fso.FileExists(runFile) Then Exit Function
  Set f = fso.OpenTextFile(runFile, 1)
  p = Trim(f.ReadLine)
  f.Close
  If p = "" Or Not IsNumeric(p) Then Exit Function
  Set procs = wmi.ExecQuery("SELECT ProcessId FROM Win32_Process WHERE ProcessId = " & CLng(p))
  If procs.Count > 0 Then Exit Function
  Set procs = wmi.ExecQuery("SELECT ProcessId FROM Win32_Process WHERE Name = '${q(exeName)}'")
  If procs.Count > 0 Then Exit Function
  Alive = False
End Function

If Not fso.FileExists(runFile) Then WScript.Quit
' 부팅 전에 남은 파일이면 (정전, 강제 전원 끄기) 무시
Dim os, bt, boot
For Each os In wmi.ExecQuery("SELECT LastBootUpTime FROM Win32_OperatingSystem")
  Set bt = CreateObject("WbemScripting.SWbemDateTime")
  bt.Value = os.LastBootUpTime
  boot = bt.GetVarDate(True)
Next
If Not IsEmpty(boot) Then
  If fso.GetFile(runFile).DateLastModified < boot Then
    fso.DeleteFile runFile, True
    WScript.Quit
  End If
End If

' 3분 넘게 기록이 없으면 PC가 꺼져 있던 것 (빠른 시작 등) → 무시
If DateDiff("s", fso.GetFile(runFile).DateLastModified, Now) > 180 Then
  fso.DeleteFile runFile, True
  WScript.Quit
End If

If Alive() Then WScript.Quit
WScript.Sleep 45000
If Alive() Then WScript.Quit

fso.DeleteFile runFile, True
sh.Run "shutdown /s /t 60 /c ""${q(MESSAGE)}""", 0, False
MsgBox "${q(MESSAGE)}", vbExclamation + vbSystemModal, "PC방 안내"
`;
}

function setupGuard(dataDir, log = () => {}) {
  if (process.platform !== 'win32') return { beat() {}, stop() {} };
  const runFile = path.join(dataDir, 'running');
  const script = path.join(dataDir, 'guard.vbs');
  const exeName = path.basename(process.execPath);
  const beat = () => { try { fs.writeFileSync(runFile, String(process.pid)); } catch {} };
  try {
    fs.writeFileSync(script, '\ufeff' + vbs(runFile, exeName).replace(/\n/g, '\r\n'), 'utf16le'); // 한글이 깨지지 않게 UTF-16
  } catch (e) { log('guard 스크립트 저장 실패: ' + e.message); }
  execFile('schtasks', ['/create', '/f', '/tn', TASK, '/sc', 'minute', '/mo', '1',
    '/tr', `wscript.exe //Nologo "${script}"`], { windowsHide: true }, (err) => { if (err) log('guard 작업 등록 실패: ' + err.message); });
  beat();
  const timer = setInterval(beat, 15_000);
  return {
    beat,
    // 정상 종료: 감시 대상에서 빠진다
    stop() { clearInterval(timer); try { fs.rmSync(runFile, { force: true }); } catch {} },
  };
}

// 빠른 자동 시작
// 윈도우는 '시작 프로그램'(레지스트리 Run)을 로그인 뒤 일부러 늦게 실행한다. 그래서
// 1) 로그인하자마자 실행되는 작업 스케줄러 작업(PCBangStart)을 등록하고 (권한이 없으면 건너뜀)
// 2) 이 사용자의 시작 프로그램 지연(StartupDelayInMSec)을 0으로 바꾼다.
// 두 방법으로 동시에 켜져도 프로그램은 하나만 실행된다.
function setupFastStart(log = () => {}) {
  if (process.platform !== 'win32') return;
  const exe = process.execPath;
  execFile('schtasks', ['/create', '/f', '/tn', 'PCBangStart', '/sc', 'onlogon', '/rl', 'limited', '/tr', `"${exe}"`],
    { windowsHide: true }, (err) => { if (err) log('빠른 시작 작업 등록 실패(권한 부족일 수 있음): ' + err.message); });
  execFile('reg', ['add', 'HKCU\\Software\\Microsoft\\Windows\\CurrentVersion\\Explorer\\Serialize',
    '/v', 'StartupDelayInMSec', '/t', 'REG_DWORD', '/d', '0', '/f'], { windowsHide: true }, () => {});
}

module.exports = { setupGuard, setupFastStart };

