files.updater.js:
// 자동 업데이트: 관리자 웹앱 주소의 guest-update/ 에서 새 버전을 확인하고 받아 둔다.
// 손님이 쓰지 않는(잠긴) 상태일 때 프로그램을 다시 시작해서 적용한다.
const path = require('path');
const fs = require('fs');
const crypto = require('crypto');

const DEFAULT_URL = 'https://geojebow.github.io/pcbang-admin/guest-update';

function newer(a, b) {
  const x = String(a).split('.').map(Number), y = String(b).split('.').map(Number);
  for (let i = 0; i < 3; i++) if ((x[i] || 0) !== (y[i] || 0)) return (x[i] || 0) > (y[i] || 0);
  return false;
}

function createUpdater({ dataDir, currentVersion, updateUrl, log = console.log }) {
  const base = (updateUrl || DEFAULT_URL).replace(/\/+$/, '');
  const updRoot = path.join(dataDir, 'update');
  let ready = null; // 받아 둔 새 버전

  // onStatus({ phase, pct }) 로 진행 상황을 알린다: checking → downloading(%) → installing → ready / latest / error
  async function check(onStatus = () => {}) {
    try {
      onStatus({ phase: 'checking' });
      const res = await fetch(`${base}/version.json?t=${Date.now()}`, { cache: 'no-store' });
      if (!res.ok) { onStatus({ phase: 'error' }); return null; }
      const info = await res.json();
      let bad = null;
      try { bad = fs.readFileSync(path.join(updRoot, 'bad-version'), 'utf8').trim(); } catch {}
      if (!info.version || !newer(info.version, currentVersion) || info.version === bad) { onStatus({ phase: 'latest' }); return null; }
      if (ready === info.version) { onStatus({ phase: 'ready', version: ready }); return ready; }

      onStatus({ phase: 'downloading', pct: 0, version: info.version });
      const bres = await fetch(`${base}/${info.bundle}?t=${Date.now()}`, { cache: 'no-store' });
      if (!bres.ok) { onStatus({ phase: 'error' }); return null; }
      // 조금씩 받으면서 몇 % 받았는지 알린다
      const total = Number(info.size) || 0;
      const chunks = [];
      let got = 0, lastPct = -1;
      const reader = bres.body.getReader();
      for (;;) {
        const { done, value } = await reader.read();
        if (done) break;
        chunks.push(Buffer.from(value)); got += value.length;
        const pct = total ? Math.min(99, Math.floor((got / total) * 100)) : 0;
        if (pct !== lastPct) { lastPct = pct; onStatus({ phase: 'downloading', pct, version: info.version }); }
      }
      const text = Buffer.concat(chunks).toString('utf8');
      onStatus({ phase: 'installing', pct: 100, version: info.version });
      const hash = crypto.createHash('sha256').update(text).digest('hex');
      if (hash !== info.sha256) { log('업데이트 파일 검증 실패'); onStatus({ phase: 'error' }); return null; }
      const bundle = JSON.parse(text);

      // 임시 폴더에 다 쓴 다음 한 번에 바꾼다
      const staging = path.join(updRoot, 'staging');
      fs.rmSync(staging, { recursive: true, force: true });
      fs.mkdirSync(staging, { recursive: true });
      for (const [name, content] of Object.entries(bundle.files)) {
        if (name.includes('..') || path.isAbsolute(name)) continue;
        const file = path.join(staging, name);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, content);
      }
      fs.writeFileSync(path.join(staging, 'version.json'), JSON.stringify({ version: info.version, date: info.date || null }));
      const current = path.join(updRoot, 'current');
      const old = path.join(updRoot, 'old');
      fs.rmSync(old, { recursive: true, force: true });
      if (fs.existsSync(current)) fs.renameSync(current, old);
      fs.renameSync(staging, current);
      fs.rmSync(old, { recursive: true, force: true });
      ready = info.version;
      log(`새 버전 ${info.version} 준비됨`);
      onStatus({ phase: 'ready', version: ready });
      return ready;
    } catch (e) {
      log('업데이트 확인 실패: ' + e.message);
      onStatus({ phase: 'error' });
      return null;
    }
  }
  return { check, get ready() { return ready; } };
}

module.exports = { createUpdater };

