// 감시 프로세스: 손님 프로그램이 작업 관리자 등으로 강제 종료되면 다시 실행한다.
// 관리자 PIN으로 정상 종료하면 quit-ok 파일에 그 프로세스 번호가 기록되고, 그때는 다시 실행하지 않는다.
// ELECTRON_RUN_AS_NODE=1 로 실행되므로 Electron 창 없이 Node처럼 동작한다.
const fs = require('fs');
const { spawn } = require('child_process');

const [parentPid, flagFile, exe, ...args] = process.argv.slice(2);

function alive(pid) {
  try { process.kill(Number(pid), 0); return true; } catch (e) { return e.code === 'EPERM'; }
}

setInterval(() => {
  if (alive(parentPid)) return;
  let allowed = '';
  try { allowed = fs.readFileSync(flagFile, 'utf8').trim(); } catch {}
  if (allowed !== String(parentPid)) {
    const env = { ...process.env };
    delete env.ELECTRON_RUN_AS_NODE;
    spawn(exe, args, { detached: true, stdio: 'ignore', env, windowsHide: false }).unref();
  }
  process.exit(0);
}, 1500);
